'use strict';
const $=(s,r=document)=>r.querySelector(s);const $$=(s,r=document)=>[...r.querySelectorAll(s)];
$$('[data-year]').forEach(e=>e.textContent=new Date().getFullYear());
const menu=$('#menu'),nav=$('#navigation');menu?.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open))});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav?.classList.contains('open')){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.focus()}});
$$('[data-filter]').forEach(b=>b.addEventListener('click',()=>{$$('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));$$('[data-category]').forEach(x=>x.hidden=b.dataset.filter!=='all'&&x.dataset.category!==b.dataset.filter)}));
const dialog=$('#look-dialog');let lastLook;$$('[data-look]').forEach(b=>b.addEventListener('click',()=>{lastLook=b;const content=$('#look-content');content.replaceChildren();const image=$('.photo',b).cloneNode(true);image.classList.add('dialog-image');const title=document.createElement('h3');title.textContent=b.dataset.title;content.append(image,title);dialog.showModal()}));$('.dialog-close')?.addEventListener('click',()=>dialog.close());dialog?.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});dialog?.addEventListener('close',()=>lastLook?.focus());
const cfg=window.GFA_CONFIG;
async function request(path,options={},token){if(!cfg?.key)throw new Error('The enquiry service is unavailable. Please contact Graceyy on WhatsApp.');const response=await fetch(cfg.url+path,{...options,headers:{apikey:cfg.key,'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{}),...options.headers}});let data=null;const text=await response.text();if(text){try{data=JSON.parse(text)}catch{data={message:'The service returned an unexpected response.'}}}if(!response.ok){const error=new Error(data?.message||data?.msg||data?.error_description||'Could not complete your request. Please try again.');error.status=response.status;throw error}return data}
const form=$('[data-enquiry]');if(form){const params=new URLSearchParams(location.search),interest=$('[name=interest]',form);const selected=params.get('interest')||(params.get('mode')==='online'?'Online training':params.get('mode')==='physical'?'Physical training':null);if(selected&&[...interest.options].some(o=>o.value===selected))interest.value=selected;if(params.get('accommodation')==='yes')$('[name=accommodation]',form).checked=true;const today=new Date();const localDate=new Date(today.getTime()-today.getTimezoneOffset()*60000).toISOString().slice(0,10);$('[name=preferred_date]',form).min=localDate;
let sending=false;form.addEventListener('submit',async e=>{e.preventDefault();if(sending||!form.reportValidity())return;const d=new FormData(form);if(d.get('website'))return;const status=$('.form-status',form),button=$('[type=submit]',form);sending=true;button.disabled=true;status.textContent='Sending your enquiry…';const payload={kind:form.dataset.enquiry,name:d.get('name').trim(),phone:d.get('phone').trim(),email:d.get('email').trim()||null,interest:d.get('interest'),preferred_date:d.get('preferred_date')||null,experience:d.get('experience')||null,accommodation:d.has('accommodation'),message:d.get('message').trim(),consent:d.has('consent')};if(payload.message.length<10||payload.name.length<2){status.textContent='Please enter your name and at least 10 characters about your enquiry.';sending=false;button.disabled=false;return}try{await request('/rest/v1/gfa_enquiries',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify(payload)});form.reset();status.textContent='Your enquiry has been sent to GFA. This does not confirm a booking or admission. If your date is close, please follow up on WhatsApp.'}catch(error){status.textContent=error.status===429||/Too many enquiries/.test(error.message)?'You’ve reached the enquiry limit. Please try later or contact Graceyy on WhatsApp.':'Your enquiry could not be confirmed. Your details remain in the form. Please try again or contact Graceyy on WhatsApp.'}finally{sending=false;button.disabled=false}})}
const staffLogin=$('#staff-login');if(staffLogin){let session;try{session=JSON.parse(localStorage.getItem('gfa_staff_session'))}catch{}const panel=$('#staff-panel'),status=$('#inbox-status');function clearSession(){session=null;localStorage.removeItem('gfa_staff_session');panel.hidden=true;staffLogin.hidden=false;$('#inbox').replaceChildren()}
async function ensureSession(){if(!session)throw new Error('Please sign in.');if(Date.now()/1000>=session.expires_at-30){session=await request('/auth/v1/token?grant_type=refresh_token',{method:'POST',body:JSON.stringify({refresh_token:session.refresh_token})});session.expires_at=Math.floor(Date.now()/1000)+session.expires_in;localStorage.setItem('gfa_staff_session',JSON.stringify(session))}return session.access_token}
async function loadInbox(){status.textContent='Loading enquiries…';try{const token=await ensureSession();const filter=$('#inbox-filter').value;const rows=await request('/rest/v1/gfa_enquiries?select=*&order=created_at.desc&limit=100'+(filter==='all'?'':'&kind=eq.'+encodeURIComponent(filter)),{},token);const inbox=$('#inbox');inbox.replaceChildren();status.textContent=rows.length?`${rows.length} most recent enquiries shown.`:'No visible enquiries. Only provisioned GFA staff can access this inbox.';for(const row of rows){const article=document.createElement('article');article.className='enquiry-card';const title=document.createElement('h3');title.textContent=row.name+' · '+row.interest;const date=document.createElement('small');date.textContent=new Date(row.created_at).toLocaleString('en-NG',{timeZone:'Africa/Lagos'})+' · '+row.kind;const contact=document.createElement('p');contact.textContent=[row.phone,row.email,row.preferred_date?'Preferred date: '+row.preferred_date:null,row.experience?'Experience: '+row.experience:null,row.accommodation?'Accommodation requested':null].filter(Boolean).join(' · ');const message=document.createElement('p');message.textContent=row.message;const label=document.createElement('label');label.textContent='Enquiry status';const select=document.createElement('select');for(const s of ['new','contacted','in_progress','closed']){const o=document.createElement('option');o.value=s;o.textContent=s.replace('_',' ');o.selected=s===row.status;select.append(o)}select.addEventListener('change',async()=>{select.disabled=true;try{await request('/rest/v1/gfa_enquiries?id=eq.'+encodeURIComponent(row.id),{method:'PATCH',headers:{Prefer:'return=representation'},body:JSON.stringify({status:select.value})},await ensureSession());status.textContent='Enquiry status updated.'}catch{select.value=row.status;status.textContent='Update failed. Please try again.'}finally{select.disabled=false}});label.append(select);article.append(title,date,contact,message,label);inbox.append(article)}}catch(error){status.textContent=error.status===401?'Your session has expired. Please sign in again.':'Unable to load the inbox. Check that your account has GFA staff access.';if(error.status===401)clearSession()}}
staffLogin.addEventListener('submit',async e=>{e.preventDefault();const b=$('button',staffLogin);b.disabled=true;$('#login-status').textContent='Signing in…';const d=new FormData(staffLogin);try{session=await request('/auth/v1/token?grant_type=password',{method:'POST',body:JSON.stringify({email:d.get('email'),password:d.get('password')})});session.expires_at=Math.floor(Date.now()/1000)+session.expires_in;localStorage.setItem('gfa_staff_session',JSON.stringify(session));staffLogin.reset();staffLogin.hidden=true;panel.hidden=false;await loadInbox()}catch{$('#login-status').textContent='Sign-in failed. Check your email and password.'}finally{b.disabled=false}});$('#sign-out').addEventListener('click',async()=>{try{await request('/auth/v1/logout',{method:'POST'},session?.access_token)}catch{}clearSession()});$('#inbox-filter').addEventListener('change',loadInbox);if(session){staffLogin.hidden=true;panel.hidden=false;loadInbox()}}
